import type { Contract } from '@/types/quotes'
import { PROVIDER_SIGNER, SignatureBlock } from './signature-block'
import { DocumentHeader } from './document-header'
import { shortHash } from '@/lib/contract-signature'

/** State of the integrity hash, computed on the server by whoever renders. */
export interface HashCheck {
  /** SHA-256 of the current contract text. */
  current: string
  /** true if it matches the hash stored at signing; false if the text changed afterwards. */
  matches: boolean
}

/** Contract rendered from contracts.body_html (generated by renderContract and editable in the panel). */
export function ContractDocument({ contract, clientName, clientCompany, hashCheck }: { contract: Contract; clientName: string; clientCompany?: string | null; hashCheck?: HashCheck | null }) {
  const signed = Boolean(contract.signed_at)
  return (
    <article className="doc mx-auto max-w-3xl bg-white text-neutral-900 p-8 md:p-12 rounded-xl shadow-sm print:shadow-none print:p-0 print:max-w-none">
      <DocumentHeader kind="Contrato" number={contract.number} />
      <div className="contract-body mt-8" dangerouslySetInnerHTML={{ __html: contract.body_html }} />
      <SignatureBlock
        caption="Firman de conformidad las partes, por duplicado, en la fecha indicada."
        signers={[
          PROVIDER_SIGNER,
          {
            title: 'El Cliente',
            name: clientName,
            detail: clientCompany ?? null,
            acceptedText: contract.signed_at
              ? `${contract.signed_signature ? 'Firmado' : 'Aceptado'} en línea por ${contract.signed_name} el ${new Date(contract.signed_at).toLocaleString('es-MX', { timeZone: 'America/Mexico_City' })}`
              : null,
            image: contract.signed_signature ?? null,
          },
        ]}
        footer={signed && contract.signed_hash ? (
          <p className="mt-8 text-[11px] leading-snug text-neutral-500 break-inside-avoid">
            Huella SHA-256 del texto aceptado: <span className="font-mono">{shortHash(contract.signed_hash)}</span> (completa: <span className="font-mono break-all">{contract.signed_hash}</span>).
            {hashCheck && (hashCheck.matches
              ? ' El texto de este documento coincide con el aceptado.'
              : ' Atención: el texto de este documento no coincide con el aceptado; el original es el de la huella.')}
          </p>
        ) : null}
      />
    </article>
  )
}
